function registerAllTools(): RegisteredToolCall[] {
	const registerTool = vi.fn();
	const server = { registerTool } satisfies ToolRegistrar;
	const runtime = createToolRuntime({
		client: null,
		catalog: {} as ExerciseTemplateCatalog,
	});
	registerHevyTools(server, runtime);
	// Snapshot the calls eagerly: Vitest 5 clears mock call history before
	// each test, so reading mock.calls inside `it` blocks would see [].
	return registerTool.mock.calls.map(([toolName, config]) => ({
		name: toolName as string,
		config: config as RegisteredToolCall["config"],
	}));
}

function getAnnotations(
	registered: RegisteredToolCall[],
	name: string,
): ToolAnnotations {
	const match = registered.find((call) => call.name === name);
	if (!match) {
		throw new Error(`Tool ${name} was not registered`);
	}
	return match.config.annotations;
}

